const item=(title,body,math='',risk='Recipe-dependent',why='Measure on your checkpoint and calibration data. This is not a measured sensitivity score.',refs=['q35'])=>({title,body,math,risk,why,refs});
export const info={
 residual:item('Residual stream','A vector per token travels through the stack. Each decoder block adds two updates: one from token mixing and one from the feed-forward network. A block is a group of operators; an individual projection is not an entire decoder block.','x → x + Mixer(Norm(x)) → x + MLP(Norm(x))','Runtime activation','Activation precision is separate from stored weight precision.'),
 norm:item('RMS normalization','Rescale each token by its root-mean-square magnitude, then apply learned channel gains. Qwen3.5/3.8 and Next use zero-centered gains (1 + weight) in the decoder norms. Earlier families use ordinary learned gains.','RMS(x) = √(mean(x²) + ε)','Precision precaution','Norm parameters are small; preserving them is a conservative policy, not proof that all lower precision fails.'),
 qkv:item('DeltaNet Q, K, V projection','One projection creates query, key, and value channels. They pass through a short causal convolution before splitting into heads. Qwen3-Next also fuses the output-gate channels into its projection; the diagram labels these slices explicitly.','[Q, K, V] = Linear(x)','Calibrate carefully','An NVFP4 study reports more output sensitivity here than in the a/b gates. Its measurements do not establish ternary safety.',['q35','next','nvfp4']),
 a:item('Decay-gate projection a','Produces one control value per value head. The value passes through softplus and combines with A_log and dt_bias to form a negative log-decay. It controls how much previous memory remains.','a = Wₐ x','Policy-protected gate','Our conservative map protects this gate. The cited NVFP4 study found a relatively small output effect for quantizing it; this is recipe-dependent.',['q35','nvfp4']),
 b:item('Write-gate projection b','Produces a scalar per value head. Sigmoid turns it into β, the strength of the key-directed memory correction. This is different from the MLP gate and the output gate z.','β = sigmoid(Wᵦ x)','Policy-protected gate','Often protected by cautious recipes. The NVFP4 study found this projection relatively robust; do not assume it is universally the most sensitive.',['q35','nvfp4']),
 z:item('DeltaNet output gate z','Controls the output after the recurrent read. The gated normalization multiplies its normalized result by SiLU(z). This gate does not directly update recurrent memory.','y = RMSNorm(read) ⊙ SiLU(z)','Calibrate carefully','Do not confuse z with the a/b memory-control gates. The NVFP4 study reports a larger output effect for z.',['q35','nvfp4']),
 conv:item('Short causal depthwise convolution','Each Q/K/V channel mixes a short history independently. Causality means future tokens are unavailable. The convolution keeps a small runtime history, separate from DeltaNet’s matrix memory. SiLU follows the convolution.','one kernel per channel; history from earlier tokens','Precision precaution','Small convolution weights were preserved in our experiments. Runtime convolution state must also survive chunk boundaries.'),
 decay:item('A_log, dt_bias, and decay','A_log and dt_bias are learned vectors. The reference computes g in float32, then the recurrence uses exp(g). The resulting decay α lies between zero and one for finite, valid parameters.','g = −exp(A_log) · softplus(a + dt_bias)\nα = exp(g)','Precision precaution','These parameters govern state dynamics. Their arithmetic precision and the precision of a projection’s weights are separate choices.'),
 beta:item('Write strength β','Sigmoid maps b into (0, 1). A small β makes a small correction; a large β moves the stored association toward the current value.','β = 1 / (1 + exp(−b))','Runtime operation','This has no standalone weight matrix.'),
 l2:item('Q/K normalization and head sharing','Queries and keys are L2-normalized for the delta rule. When there are more value heads than key heads, Q/K heads are repeated to align with the value heads. The read also scales Q by 1/√dₖ.','q̂ = q / ‖q‖₂; k̂ = k / ‖k‖₂','Runtime operation','Normalization affects numerical stability; it is not a quantization format.'),
 state:item('Persistent recurrent state','Each value head maintains a key-by-value matrix. It summarizes past associations in fixed space rather than keeping every past token. Preserve this state between chunks of one sequence; reset at a real sequence boundary.','S shape = [batch, value heads, key dim, value dim]','State precision','Quantizing state is a separate experiment from quantizing weights. Memory estimates here use an explicit state dtype.',['q35','delta','cache']),
 delta:item('Decay → prediction → correction → read','The implementation first decays old memory. It reads what that decayed memory predicts for the current key, forms a correction toward v, writes the correction along k, and reads using q. Training can evaluate the same recurrence with chunkwise parallel algorithms.','S̄ = αSₜ₋₁\ne = β(v − S̄ᵀk)\nSₜ = S̄ + keᵀ\no = Sₜᵀ(q / √dₖ)','Runtime operation','This ordering follows the reference code. Kernel layout and rounding may differ. The memory lab is a 2D teaching example.',['q35','delta']),
 gatednorm:item('Gated RMS normalization','Normalize the recurrent read separately within each value head, apply a learned gain, then multiply by SiLU(z). This is not the zero-centered decoder RMSNorm.','RMSNorm(o) ⊙ SiLU(z)','Precision precaution','Keep the distinction between normalization weights, output-gate projection, and runtime arithmetic.'),
 out:item('Output projection','Mix the token-mixer heads back into the model’s residual width. The output is added to the block input by the first residual connection.','head channels → hidden size','Calibrate carefully','Output projections can expose large activation outliers. Inspect activation-weighted error and downstream quality.'),
 q:item('Query projection','Queries describe what each current token looks for. In hybrid Qwen attention, q_proj also contains a separate output-gate slice. The gate bypasses Q/K normalization and RoPE.','Q = xWqᵀ','Recipe-dependent','Quantization changes attention scores; validate representative long-context inputs.'),
 k:item('Key projection','Keys describe how tokens can be addressed. Qwen uses fewer KV heads than query heads in grouped-query attention, reducing cache size.','K = xWkᵀ','Recipe-dependent','Weight error and cache-storage error are distinct.'),
 v:item('Value projection','Values contain information combined by the attention weights. Values are cached but do not receive RoPE.','V = xWvᵀ','Recipe-dependent','Evaluate with the same cache precision as the comparison baseline.'),
 qknorm:item('Per-head Q/K RMSNorm','Normalize query and key features within each head before applying positional rotation. Qwen3-family attention includes this step; it is absent from the Qwen2 template.','Q → RMSNorm → RoPE; K → RMSNorm → RoPE','Precision precaution','A small learned norm parameter is distinct from the much larger Q/K projections.',['q35','q3']),
 heads:item('Head reshape','Rearrange projected channels into attention heads. This changes tensor layout, not values or learned parameters.','','Runtime operation','No weight tensor to quantize.'),
 rope:item('Rotary positional embedding','Rotate paired Q/K channels using their positions. Hybrid models may rotate only a fraction of each head. Multimodal Qwen variants allocate rotary dimensions across temporal and spatial coordinates. Values are not rotated.','position-aware Q and K','Runtime operation','Long-context behavior depends on the actual RoPE config and scaling. A config limit is not a measured quality guarantee.',['q35','vl','vl3']),
 kv:item('Attention key/value cache','Store prior keys and values so decoding does not recompute them. GQA shares KV heads among several query heads. This cache grows with context; DeltaNet matrix state does not.','2 × layers × tokens × KV heads × head dim × bytes','State precision','KV quantization needs its own calibration and validation. This diagram does not execute a cache.',['cache','q35']),
 attention:item('Causal grouped-query attention','Compare each query with allowed keys, scale scores, apply the causal mask and softmax, then mix values. Several query heads share a KV head. FlashAttention changes the execution strategy, not this mathematical dependency.','softmax(QKᵀ / √d + causal mask) V','Runtime operation','Softmax scores, KV storage, and projection weights have different precision requirements.',['q35','q3','q2']),
 sliding:item('Sliding-window causal attention','Restrict attention to a configured recent window. This is still softmax attention, not DeltaNet. The model map distinguishes it from full attention.','causal attention over recent keys only','Runtime operation','The memory estimator gives an upper bound by counting the full context.',['q2','cache']),
 attngate:item('Attention output gate','The gated-attention reference splits gate channels from q_proj and multiplies the attended result by sigmoid(gate) before o_proj. This is separate from DeltaNet’s SiLU output gate.','attention output ⊙ sigmoid(gate)','Recipe-dependent','The loaded config is shown in the inspector; custom implementations may use a different gate.'),
 add:item('Residual addition','Add the sublayer update to its input. The skip connection carries the original residual stream around the entire sublayer. This addition is not concatenation.','y = skip + update','Runtime operation','The paths must have the same shape. Errors from earlier quantized blocks affect later block inputs.'),
 mlpgate:item('SwiGLU gate projection','Project into the intermediate width and apply SiLU. This feature-wise gate multiplies a second linear branch; it does not route tokens to experts.','SiLU(Wgate x)','Recipe-dependent','This large matrix is usually part of a quantization target set. Validate against representative activations.',['q35','q3','q2']),
 up:item('MLP up projection','Expand token features into the intermediate width. Its output is multiplied by the activated gate branch.','up = Wup x','Recipe-dependent','Low-rank factorization can reduce storage, but rank is an accuracy-versus-size choice.',['q35','q3']),
 product:item('SwiGLU feature product','Multiply the activated gate and the up-projection output element by element. This introduces a nonlinear interaction before the down projection.','SiLU(Wgate x) ⊙ Wup x','Runtime operation','No standalone learned tensor.',['q35','q3']),
 down:item('MLP down projection','Return intermediate features to the residual width. It is followed by the second residual addition.','Wdown [SiLU(Wgate x) ⊙ Wup x]','Calibrate carefully','The multiplicative MLP may create large intermediate activations. Validate this projection in context.',['q35','q3']),
 router:item('Mixture-of-experts router','Compute scores over experts and select a configured top-k set per token. Routing weights combine their outputs. Small score changes near a selection boundary can change which experts run.','token → router scores → top-k experts','Routing precaution','This is a structural reason for caution, not a measured per-layer sensitivity ranking.',['moe','next']),
 experts:item('Routed expert feed-forward networks','Each selected expert is a gated feed-forward network. Only the selected experts contribute for a token; the full model still stores all expert weights. The card represents a bank of experts, not one shared dense MLP.','each expert: down(SiLU(gate(x)) ⊙ up(x))','Recipe-dependent','Total parameters and active parameters are different. Shapes reflect the loaded expert configuration.',['moe','next']),
 shared:item('Shared expert path','In supported hybrid MoE families, a shared expert runs alongside routed experts. Its output is modulated by a learned sigmoid gate and added to the routed mixture.','','Recipe-dependent','Do not invent a shared expert for models whose config has none.',['next']),
 combine:item('Weighted expert combination','Combine selected expert outputs using router weights. Where configured, add the gated shared-expert output before the residual addition.','','Runtime operation','Routing normalization depends on the model implementation.',['moe','next']),
 embeddings:item('Token embeddings','The tokenizer maps text to token IDs; the embedding table turns each ID into a hidden-width vector. Multimodal models insert visual embeddings at designated positions before decoder processing.','weight shape = [vocabulary, hidden size]','Vocabulary precaution','Head/embedding tying is read from the config. The 27B presets have separate matrices; the 0.8B preset ties them.',['config','q35']),
 finalnorm:item('Final decoder normalization','After the last decoder block, a final RMSNorm prepares hidden states for the output head. It is outside the numbered decoder blocks.','','Precision precaution','Include this step when reconstructing or comparing final-head inputs.',['q35','q3']),
 head:item('Language-model output head','Project the final hidden vector into one logit per vocabulary entry. Sampling or argmax chooses the next token. The head is after the final normalization. It can share weights with embeddings only when tying is configured.','logits = hidden · Wheadᵀ','Vocabulary precaution','Quantizing a large vocabulary matrix changes storage substantially. Check its quality separately and count tied storage once.',['q35','config']),
 vision:item('Vision frontend','Images and videos become spatiotemporal patches. A vision transformer processes patch features; a merger projects and reduces them into text-width visual tokens. The language decoder receives these with text embeddings. Qwen2.5-VL uses windowed vision attention; Qwen3-VL can also inject DeepStack features.','','Separate subsystem','The decoder diagram does not flatten the vision transformer into the text stack. Vision layout is summarized from the loaded config.',['vl','vl3','q35']),
 mtp:item('Multi-token prediction','The config may declare auxiliary multi-token-prediction depth. MTP supports training and compatible speculative inference paths. It is not an extra ordinary decoder block traversed by every basic next-token forward.','','Implementation-dependent','A config declaration does not prove a serving engine uses MTP.',['q35','next']),
 unknown:item('Unsupported family or operator','The imported config can still show depth and dimensions. Exact internal flow requires a verified family adapter; this app will not silently render a different architecture.','','Unknown','Add an adapter and tests against the model implementation.',['config'])
};
export const lessons=[
 {title:'A model, a block, a layer',tag:'Start here',text:'A model contains embeddings, a stack of decoder blocks, a final norm, and an output head. Each block contains many smaller layers: projections, norms, and nonlinear operations. Click a numbered block to inspect its computation graph.',refs:['q35']},
 {title:'Why mix DeltaNet with attention?',tag:'Hybrid design',text:'DeltaNet compresses history into a fixed-size matrix, making recurrent decode state independent of context length. Full attention retains a growing list of keys and values and can address earlier tokens directly. Hybrid configurations interleave both. The app reads the actual schedule instead of assuming every Qwen has a 3:1 pattern.',refs:['delta','q35','next']},
 {title:'Prefill, decode, and chunk boundaries',tag:'Execution',text:'Prefill processes the prompt, often in parallel or chunks. Decode adds tokens while reusing state. Resetting KV or recurrent state at an arbitrary chunk boundary changes the computation. Mathematical equivalence does not imply bit-identical outputs across kernels or dtypes.',refs:['cache','q35']},
 {title:'Sensitivity is a measurement',tag:'Quantization',text:'Amber marks a conservative precision precaution; teal and purple identify mixer types. None is a universal sensitivity score. A recent NVFP4 study on Qwen3.8-27B reports robust a/b gates under its calibrated recipe. That finding does not prove the same result for ternary factorization, another calibration set, or another runtime.',refs:['nvfp4']},
 {title:'Weights, activations, and state',tag:'Precision',text:'Stored weights, runtime activations, accumulation, KV cache, and recurrent state are different precision choices. A 4-bit weight file does not mean all arithmetic is 4-bit. Scales, headers, padding, and protected tensors contribute to actual storage.',refs:['nvfp4','cache']},
 {title:'Dense versus experts',tag:'MoE',text:'A dense feed-forward layer processes every token through the same matrices. An MoE router selects several expert networks per token. Active parameter count describes compute participation; total parameter count describes the full model inventory.',refs:['q3','moe']},
 {title:'The 27B family is multimodal',tag:'Vision',text:'The bundled 27B configs include a vision transformer frontend. Its blocks are distinct from the 64 text decoder blocks. Text-only inference bypasses visual input processing; it does not turn the vision blocks into text blocks.',refs:['config','q35']},
 {title:'Reconstruction versus packing',tag:'Your experiments',text:'Reconstruction changes quantized parameters to reduce output error. A lossless codec only changes their representation. Verify exact codes, scales, rebuilt weights, and matched evaluation. Neither the number 37 nor a fractional radix determines a neural architecture.',refs:['q35']}
];
